//! Resumable performance/reliability workflow fabric for Worldgen P21.
use super::performance_reliability_copilot_support::{self,PerformanceReliabilityCopilotRequest,PerformanceReliabilityCopilotReceipt};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::json;
use std::collections::BTreeSet;
use thiserror::Error;
pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.performance-reliability-workflow-receipt+json";
const BOUNDARY:&str="preclinical-research-only; no human-subject or clinical-source data; no diagnosis, treatment, triage, enrollment, or clinical decisions";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct PerformanceReliabilityWorkflowRequest{pub workflow_id:String,pub copilot:PerformanceReliabilityCopilotRequest,pub stage_order:Vec<String>,pub completed_stage_order:Vec<String>,pub checkpoint_seq:u64,pub budget_units:u64,pub compensation_enabled:bool,pub replay_identity:ContentHash}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct PerformanceReliabilityWorkflowReceipt{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub workflow_id:String,pub disposition:String,pub stage_order:Vec<String>,pub completed_stage_order:Vec<String>,pub pending_stage_order:Vec<String>,pub compensation_order:Vec<String>,pub checkpoint_seq:u64,pub budget_units:u64,pub consumed_units:u64,pub replay_identity:ContentHash,pub copilot:PerformanceReliabilityCopilotReceipt,pub workflow_digest:ContentHash,pub artifact:serde_json::Value,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum PerformanceReliabilityWorkflowError{#[error("invalid reliability workflow request: {0}")]Invalid(String),#[error("invalid reliability workflow receipt: {0}")]Receipt(String),#[error("reliability workflow artifact failed: {0}")]Artifact(String)}
fn h(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn o(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}
impl PerformanceReliabilityWorkflowReceipt{pub fn validate(&self)->Result<(),PerformanceReliabilityWorkflowError>{if self.schema_version!="aurora-research-contract/1.0"||self.boundary!=BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.workflow_id.trim().is_empty()||self.stage_order.is_empty()||self.checkpoint_seq==0||self.budget_units==0||self.consumed_units>self.budget_units||![&self.replay_identity,&self.workflow_digest].into_iter().all(h)||self.artifact.get("content_hash").and_then(|v|v.as_str())!=Some(self.workflow_digest.as_str()){return Err(PerformanceReliabilityWorkflowError::Receipt("reliability workflow identity, budget, locality, or digest is incomplete".into()))}for v in [&self.stage_order,&self.completed_stage_order,&self.pending_stage_order,&self.compensation_order,&self.effect_receipts]{if !o(v){return Err(PerformanceReliabilityWorkflowError::Receipt("reliability workflow ordering is not canonical".into()))}}let ids=self.stage_order.iter().cloned().collect::<BTreeSet<_>>();let parts=self.completed_stage_order.iter().chain(&self.pending_stage_order).cloned().collect::<BTreeSet<_>>();if ids!=parts{return Err(PerformanceReliabilityWorkflowError::Receipt("reliability workflow stages do not partition".into()))}Ok(())}}
pub fn manifest(feature_id:&str,version:&str,scale:&str)->serde_json::Value{json!({"schema_version":"aurora-research-contract/1.0","capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["reliability engineer","workflow orchestrator","research program lead"],"behavior":format!("orchestrate resumable reliability assessment for {scale}"),"value":"makes workload qualification restartable, budgeted, compensating, and replayable without hidden retries","input_schema":"PerformanceReliabilityWorkflowRequest1@1","output_schema":"PerformanceReliabilityWorkflowReceipt1@1","effects":["schedule:reliability-workflow","block:unsafe-release"],"permissions":["schedule:bounded-reliability-workflow"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
pub fn schedule(r:&PerformanceReliabilityWorkflowRequest,feature_id:&str,version:&str,scale:&str,require_approval:bool)->Result<PerformanceReliabilityWorkflowReceipt,PerformanceReliabilityWorkflowError>{if r.workflow_id.trim().is_empty()||r.stage_order.is_empty()||r.stage_order!={let mut x=r.stage_order.clone();x.sort();x.dedup();x}||r.checkpoint_seq==0||r.budget_units==0||!r.compensation_enabled||!h(&r.replay_identity)||r.copilot.reliability_request.replay_identity!=r.replay_identity{return Err(PerformanceReliabilityWorkflowError::Invalid("reliability workflow request is invalid".into()))}let completed=r.completed_stage_order.iter().cloned().collect::<BTreeSet<_>>();if completed.iter().any(|x|!r.stage_order.contains(x)){return Err(PerformanceReliabilityWorkflowError::Invalid("reliability workflow completed stage is undeclared".into()))}let copilot=performance_reliability_copilot_support::run(&r.copilot,feature_id,version,scale,require_approval).map_err(|e|PerformanceReliabilityWorkflowError::Invalid(e.to_string()))?;let pending=r.stage_order.iter().filter(|x|!completed.contains(*x)).cloned().collect::<Vec<_>>();let consumed=(r.copilot.workload_order.len()as u64).min(r.budget_units);let compensation=if copilot.disposition=="blocked"{vec![format!("workflow:{}:retain-reliability-verdict",r.workflow_id)]}else{Vec::new()};let disposition=if copilot.disposition=="blocked"{"blocked"}else if pending.is_empty(){"qualified"}else{"partial"};let effects=if disposition=="qualified"{vec![format!("schedule:reliability-workflow:{}",r.workflow_id)]}else{vec!["block:unsafe-release".into()]};let payload=json!({"schema_version":"aurora-research-contract/1.0","contract_version":version,"feature_id":feature_id,"workflow_id":r.workflow_id,"disposition":disposition,"stage_order":r.stage_order,"completed_stage_order":completed,"pending_stage_order":pending,"compensation_order":compensation,"checkpoint_seq":r.checkpoint_seq,"budget_units":r.budget_units,"consumed_units":consumed,"replay_identity":r.replay_identity,"copilot":copilot.clone(),"effect_receipts":effects,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let d=ContentHash::of_value(&payload).map_err(|e|PerformanceReliabilityWorkflowError::Artifact(e.to_string()))?;let strings=|k:&str|payload[k].as_array().map(|a|a.iter().filter_map(|v|v.as_str().map(String::from)).collect()).unwrap_or_default();let out=PerformanceReliabilityWorkflowReceipt{schema_version:"aurora-research-contract/1.0".into(),contract_version:version.into(),feature_id:feature_id.into(),workflow_id:r.workflow_id.clone(),disposition:disposition.into(),stage_order:r.stage_order.clone(),completed_stage_order:completed.iter().cloned().collect(),pending_stage_order:strings("pending_stage_order"),compensation_order:strings("compensation_order"),checkpoint_seq:r.checkpoint_seq,budget_units:r.budget_units,consumed_units:consumed,replay_identity:r.replay_identity.clone(),copilot,workflow_digest:d.clone(),artifact:json!({"content_type":CONTENT_TYPE,"content_hash":d,"boundary":BOUNDARY}),effect_receipts:strings("effect_receipts"),raw_data_local:true,aggregate_only:true,boundary:BOUNDARY.into()};out.validate()?;Ok(out)}

